   132	    let kind = match error {
   133	        ControlledError::Original(CssError::Limit) => ErrorKind::Limit(LimitKind::PaintVisits),
   134	        ControlledError::Original(CssError::OutOfMemory) | ControlledError::OutOfMemory => {
