    42	impl<'a> FrameBuilder<'a> {
    43	    pub fn new(base: SceneView<'a>, byte_limit: usize) -> Result<Self> {
    44	        if base.scene(base.id).is_none() {
    45	            return Err(invalid(0));
    46	        }
    47	        Ok(Self {
    48	            frame: EvaluatedFrame {
    49	                base,
    50	                edges: None,
    51	                colors: None,
    52	                shapes: None,
    53	                fill_paints: None,
    54	                stroke_paints: None,
