    62	    fn incoming(&mut self, new: usize, old: usize) -> Result<()> {
    63	        let peak = add(self.frame.stats.live_bytes, new)?;
    64	        if peak > self.byte_limit {
    65	            return Err(limit(LimitKind::ReservedBytes));
    66	        }
    67	        let live = add(self.frame.stats.live_bytes - old, new)?;
    68	        let history = add(self.frame.stats.total_allocated_bytes, new)?;
    69	        let count = self
    70	            .frame
    71	            .stats
    72	            .allocation_count
    73	            .checked_add(usize::from(new != 0))
    74	            .ok_or_else(arithmetic)?;
    75	        self.frame.stats.live_bytes = live;
    76	        self.frame.stats.peak_live_bytes = self.frame.stats.peak_live_bytes.max(peak);
    77	        self.frame.stats.total_allocated_bytes = history;
    78	        self.frame.stats.allocation_count = count;
    79	        Ok(())
    80	    }
    81	    fn copy<T: Copy>(&mut self, source: &[T], control: &mut dyn WorkControl) -> Result<Vec<T>> {
    82	        control.checkpoint().map_err(stopped)?;
    83	        let requested = source
    84	            .len()
    85	            .checked_mul(std::mem::size_of::<T>())
    86	            .ok_or_else(arithmetic)?;
    87	        if add(self.frame.stats.live_bytes, requested)? > self.byte_limit {
    88	            return Err(limit(LimitKind::ReservedBytes));
    89	        }
    90	        let mut values = Vec::new();
    91	        values
    92	            .try_reserve_exact(source.len())
    93	            .map_err(|_| Diagnostic {
    94	                kind: ErrorKind::OutOfMemory,
    95	                offset: 0,
    96	            })?;
    97	        let actual = bytes(&values)?;
    98	        self.incoming(actual, 0)?;
    99	        for item in source {
   100	            if let Err(stop) = control.charge(WorkKind::AnimationTransform, 1) {
   101	                self.frame.stats.live_bytes -= actual;
   102	                return Err(stopped(stop));
   103	            }
   104	            values.push(*item);
   105	        }
