a>, paint_cache: PaintCache, text_cache: TextCache, builder: SceneBuilder, options: DecodeOptions<'a>, continuations: Vec<Continuation>, active: ActiveDefinitions } // shared interface and state layout frozen by coordinator; module owners cannot add cross-module callbacks\",\n41:    \"Plans\": \"enum DefinitionKind { Clip, Mask, Pattern, Marker, Filter } enum TextAnchor { Start, Middle, End } struct ImageView<'a> { rgba: &'a [u8], byte_count: usize, row_stride: usize, width: u32, height: u32 } enum Continuation { Enter(TraversalFrame), Exit(PostOperation), AwaitPattern(PatternTicket) } struct TraversalFrame { scene: SceneId, first: usize, limit: usize, current: usize, render_depth: usize, transform: Affine, viewport: [f64;2], inherited_style: StyleSpans, flavor: DecodeFlavor, transform_node: Option<TransformId>, group: Option<GroupId>, text_state: TextState, preserve_space: bool } struct StyleSpans { values: [Option<XmlSpan>;39] } // spans resolved only against same external source, CSS provenance unchanged\",\n42:    \"ActiveDefinitions\": \"struct DefinitionIdentity { kind: DefinitionKind, element: ElementId } struct ActiveDefinitions { uses: Vec<ElementId>, masks: Vec<ElementId>, patterns: Vec<ElementId>, markers: Vec<ElementId> } // all admission caps from C, explicit push/pop on continuation unwind; nested counters reference same job ledger, not copies\",\n43:    \"Caches\": \"struct PaintCache { entries: Vec<GradientCacheEntry>, slots: Vec<Option<usize>>, token_visits: usize } struct GradientCacheEntry { definition: ElementId, paint: Paint, stop_range: TableRange } struct TextCache { entries: Vec<TextCacheEntry>, text_bytes: usize, commands: usize } struct TextCacheEntry { text: Vec<u8>, family_spans: Vec<Span>, owned_families: Vec<Vec<u8>>, size_points: f64, weight: f64, letter_spacing_points: f64, style: TextStyle, layout: TextLayout } // complete request equality, no family raw-pointer retention; CSS/ref/gradient/endpoint caches die with decode; token endpoint cache one entry per token and attribute ranges reuse indices\",\n44:    \"DecodeOperations\": \"trait DecodeOperations { fn resolve_paint(&mut self, ctx: &mut ResolveContext<'_>, value: XmlSpan, edges: &[Edge], inverse: Affine, viewport: [f64;2], control: &mut dyn WorkControl) -> Result<ResolvedPaint>; fn plan_definition<'src, 'ctx>(&mut self, ctx: &mut DefinitionContext<'src, 'ctx>, kind: DefinitionKind, element: ElementId, owner: ShapeId, transform: Affine, bounds: [f64;4], style: &CssPaint<'src>, control: &mut dyn WorkControl) -> Result<DefinitionPlan<'src>>; fn decode_text(&mut self, request: TextDecodeRequest<'_>, builder: &mut SceneBuilder, control: &mut dyn WorkControl) -> Result<bool>; fn decode_image(&mut self, request: ImageDecodeRequest<'_>, builder: &mut SceneBuilder, control: &mut dyn WorkControl) -> Result<ShapeId>; } // actual coordinator adapter delegates entire PAINT/DEFINITIONS/MEDIA implementations. Compile each module against shared trait declarations, no stubs/unfinished peer bodies. No method recurses into Decoder; 'src is the source/paint lifetime, independent of the mutable context borrow, control and caller-owned counters.\",\n45:    \"MediaDecodeRequests\": \"struct TextDecodeRequest<'a> { element: ElementView<'a>, end: usize, style: &'a CssPaint<'a>, transform: Affine, state: &'a mut TextState, preserve_space: bool, provider: &'a mut dyn MediaProvider, cache: &'a mut TextCache } struct ImageDecodeRequest<'a> { element: ElementView<'a>, style: &'a CssPaint<'a>, transform: Affine, provider: &'a mut dyn MediaProvider } // transient borrowed request only, not retained\",\n46:    \"FlatKernel\": \"trait FlatKernel { fn render_flat(&mut self, view: SceneView<'_>, range: TableRange, options: RenderOptions, control: &mut dyn WorkControl) -> Result<RenderResult>; } // coordinator implements with full original flat kernel using RASTER_INDEX/SAMPLE. Group owner depends only on shared interface, never decoder/pipeline. Each grouped range calls actual scalar kernel, no reduced renderer/provider.\",\n48:    \"KernelResources\": \"trait KernelResources { fn paint_sample(&self, paint: &Paint, stops: &[PaintStop], x: f64, y: f64) -> [u8;4]; fn clip_contains(&self, view: SceneView<'_>, clip: ClipId, x: f64, y: f64) -> bool; fn clip_boundary_edges(&self, view: SceneView<'_>, clip: ClipId, visitor: &mut dyn FnMut(Edge) -> bool) -> Result<bool>; fn clip_work_counts(&self, view: SceneView<'_>, clip: ClipId) -> Result<ClipWorkCounts>; fn stroke_sample_work(&self, view: SceneView<'_>, shape: ShapeId, cache: &DashCache, x: f64, y: f64) -> (usize,bool,bool); } // actual coordinator adapter binds PAINT/DEFINITIONS/RASTER_SAMPLE pure operations. Frozen interface allows RASTER_INDEX/SAMPLE to compile disjointly, no fake/stub implementation accepted.\"\n53:      \"name\": \"decode\",\n54:      \"signature\": \"fn decode(source: &SourceOwner, generation: u64, options: DecodeOptions<'_>, control: &mut dyn WorkControl) -> Result<SceneGraph>\",\n55:      \"contract\": \"Collect accepted XML stream with take(); lexical source/tokens owners live outside Decoder borrows. Create one CSS sheet/reference index and endpoint/attribute caches; drive events, render child patterns and resume at exact original traversal position; parse owned animation last; publish only after freeze. All legacy variants select options/measurement, not independent decoders.\"\n59:      \"name\": \"Decoder::new\",\n60:      \"signature\": \"fn new(source: &'a SourceOwner, tokens: &'a [XmlToken], generation: u64, options: DecodeOptions<'a>, control: &mut dyn WorkControl) -> Result<Decoder<'a>>\",\n61:      \"contract\": \"Own builder and bounded continuation stack, borrow external immutable source/tokens, own ephemeral CSS/reference caches borrowing same external data. No self reference. Cancellation invalidates draft and outstanding tickets.\"\n65:      \"name\": \"Decoder::step\",\n66:      \"signature\": \"fn step<'s>(&'s mut self, work_quantum: u64, operations: &mut dyn DecodeOperations, control: &mut dyn WorkControl) -> Result<DecodeEvent<'s>>\",\n71:      \"name\": \"Decoder::resume_pattern\",\n72:      \"signature\": \"fn resume_pattern(&mut self, ticket: PatternTicket, result: Result<Tile>, control: &mut dyn WorkControl) -> Result<()>\",\n73:      \"contract\": \"After request view borrow ends, validate ticket/dimensions/capacity; move rendered pixels once into pattern; update cache/budget then continue same position. Error aborts job, no fallback or skipping. Nested patterns finish before parent event.\"\n77:      \"name\": \"Decoder::finish\",\n79:      \"contract\": \"Only Complete state allowed; all indices/ranges/inverses/graph and pattern readiness checked; move arrays and Arc clone, no parsing or source copy.\"\n83:      \"name\": \"SceneBuilder operations\",\n85:      \"contract\": \"Every append transaction covers colors/IDs/stroke/dashes/source and path table rebases; rollback drops media/temp allocations once; error commits no partially visible shape. Private mutable table access through mark-scoped writer only.\"\n89:      \"name\": \"read tables\",\n90:      \"signature\": \"fn root(&self) -> SceneView<'_>; fn source(&self) -> &[u8]; fn source_owner(&self) -> &SourceOwner; fn tables(&self) -> ViewTables<'_>; fn shape(&self, id: ShapeId) -> Option<&Shape>; fn fill_paint(&self, id: ShapeId) -> Option<&Paint>; fn stroke_paint(&self, id: ShapeId) -> Option<&Paint>; fn dash_values(&self, id: ShapeId) -> Option<&[f64]>\",\n95:      \"name\": \"geometry\",\n97:      \"contract\": \"Entire shape_geometry/path/custom API: primitives, poly lists, transformed tolerance, implicit fill closure, open stroke, source numbers/segments/subpaths. Reuse accepted path parser and G3 flatten/number cursor; custom glyph/image geometry passes owned edges/metadata into same style finalization transaction.\"\n101:      \"name\": \"style\",\n102:      \"signature\": \"fn parse_style(source: &[u8], paint: &CssPaint<'_>, percentage_reference: f64, transform: Affine, viewport: Viewport, builder: &mut SceneBuilder, control: &mut dyn WorkControl) -> Result<ResolvedStyle>\",\n103:      \"contract\": \"ResolvedStyle owns fill [u8;4], Stroke, fill/stroke server spans, clip/filter/mask/marker spans, opacity, visibility/display, blend/isolation; no borrowed CSS retained after decode. Preserve currentColor, dash compaction, alpha rounding, non-scaling stroke, join fallback, crisp edges and paint order.\"\n107:      \"name\": \"resolve\",\n109:      \"contract\": \"ResolveContext borrows source/tokens + mutable CSS/reference/cache and stop append transaction; ResolvedPaint contains Paint and owned new stops before commit. Local linear/radial href inheritance, stop CSS/currentColor, ordering, spread, focal/radius defaults, bbox/inverse handling unchanged. Pattern classified and sent to planner. Cache keyed complete resolution context, charge all probes/token visits.\"\n113:      \"name\": \"sample\",\n119:      \"name\": \"plan definitions\",\n121:      \"contract\": \"DefinitionContext supplies borrowed source/tokens + mutable CSS/reference and shared counters/active-definition stack, builder append interface; DefinitionPlan<'src> contains one or more Expansion<'src> with source-borrowed CssPaint<'src>, postoperation and full parsed descriptor. CssSheet<'src> and ReferenceIndex<'src> retain their accepted source borrows; DefinitionContext<'src, 'ctx> separately ties mutable container, active-stack, counter and builder borrows to temporary 'ctx, while the result retains only 'src. Control is separately borrowed. This permits the context and all mutable control borrows to end when the method returns DefinitionPlan<'src>. Includes all clip/filter/mask/pattern/marker files, strict local hrefs, units, regions, viewBox, definition ancestor style, cache keys and instance limits. Engine executes expansions; definitions never recurse into engine directly.\"\n125:      \"name\": \"clip mutation\",\n131:      \"name\": \"clip queries\",\n137:      \"name\": \"text/image builders\",\n139:      \"contract\": \"Preserve tspan state/x-y-dx-dy, entities, whitespace, font fallback/style/anchor/spacing, source mapping; image exact PNG/JPEG data URI grammar and bilinear premultiplied sample placement/meet/slice. TextCache owns key text and family bytes/spans within source lifetime plus owned layouts; caller borrows cache hits, no multiple release. No product deterministic fake provider.\"\n143:      \"name\": \"queries\",\n144:      \"signature\": \"fn bounds(view: SceneView<'_>, shape: ShapeId) -> Option<Selection>; fn hit_test(view: SceneView<'_>, x: f64, y: f64, tolerance: f64) -> Option<Selection>; fn element_at_offset(view: SceneView<'_>, offset: usize) -> Option<Selection>; fn source_assign(builder: &mut SceneBuilder, scene: SceneId, shapes: TableRange, source: Span) -> Result<()>\",\n145:      \"contract\": \"Reverse painter order, most-specific rendered source range, exact old fill/stroke tolerance/clip behavior; IDs instance-specific and generation checked. Invalid/nonfinite arguments do not panic.\"\n149:      \"name\": \"allocation tracking\",\n155:      \"name\": \"bounds\",\n156:      \"signature\": \"fn build_bounds(view: SceneView<'_>, map: ViewMapping, resources: &dyn KernelResources, control: &mut dyn WorkControl) -> Result<BoundsSet>; fn mark_boundaries(view: SceneView<'_>, map: ViewMapping, resources: &dyn KernelResources, control: &mut dyn WorkControl) -> Result<BoundaryMask>; fn mark_clip_boundaries(view: SceneView<'_>, map: ViewMapping, boundary: &mut BoundaryMask, resources: &dyn KernelResources, control: &mut dyn WorkControl) -> Result<()>; fn boundary_test(mask: &BoundaryMask, pixel: usize) -> bool\",\n157:      \"contract\": \"Bounds include every paintable scalar sample: caps/joins/dashes/clips. Full boundary marking on invalid clip inverse. Preserve conservative degenerate/full-tile cases; 200M boundary-work cap; own/drop arrays. KernelResources is passed explicitly to operations requiring clip/stroke queries; lower writer consumes the shared interface and the coordinator supplies actual implementations.\"\n161:      \"name\": \"scanline\",\n162:      \"signature\": \"fn create_scanlines(view: SceneView<'_>, bounds: &BoundsSet, map: ViewMapping, resources: &dyn KernelResources, control: &mut dyn WorkControl) -> Result<ScanlineIndex>; fn reset_scanlines(index: &mut ScanlineIndex); fn build_row(index: &mut ScanlineIndex, view: SceneView<'_>, pixel_y: u32, rows: &mut RowBuffers, resources: &dyn KernelResources, control: &mut dyn WorkControl) -> Result<usize>\",\n163:      \"contract\": \"Original event/tree algorithm, 5 samples rows, active capacities explicit, no hidden allocations per row; ascending shape painter order, original tiebreaks. KernelResources is passed explicitly to operations requiring clip/stroke queries; lower writer consumes the shared interface and the coordinator supplies actual implementations.\"\n167:      \"name\": \"fill cache\",\n168:      \"signature\": \"fn create_fill_cache(view: SceneView<'_>, resources: &dyn KernelResources, control: &mut dyn WorkControl) -> Result<FillCache>; fn eligible(cache: &FillCache, shape: ShapeId) -> bool; fn color(view: SceneView<'_>, shape: ShapeId) -> Option<[u8;4]>; fn build_fill_row(cache: &mut FillCache, view: SceneView<'_>, shape: ShapeId, y: u32, map: ViewMapping, rows: &RowBuffers, resources: &dyn KernelResources, control: &mut dyn WorkControl) -> Result<FillRowWork>; fn build_runs(cache: &mut FillCache, view: SceneView<'_>, bounds: PixelBounds, y: u32, boundary: &BoundaryMask, map: ViewMapping, resources: &dyn KernelResources, control: &mut dyn WorkControl) -> Result<usize>; fn pixel_runs(cache: &FillCache) -> &[PixelRun]; fn interval_pixel_range(view: SceneView<'_>, bounds: PixelBounds, map: ViewMapping, sample_offset: f64, interval: FillInterval) -> Result<(TableRange,usize)>; fn fill_contains(cache: &FillCache, sample_row: usize, x: f64) -> (bool,usize)\",\n169:      \"contract\": \"FillRowWork records edge_visits/work_units. Entire uniform fill eligibility/exclusions, heap sort crossings/winding/interval algorithms and binary comparisons stay; >4096-edge shapes use original scalar fallback rather than refusal. KernelResources is passed explicitly to operations requiring clip/stroke queries; lower writer consumes the shared interface and the coordinator supplies actual implementations.\"\n173:      \"name\": \"preflight\",\n174:      \"signature\": \"fn work_budget(width: u32, height: u32) -> u64; fn preflight(view: SceneView<'_>, scratch: &mut RasterScratch, map: ViewMapping, stats: &mut WorkStats, resources: &dyn KernelResources, control: &mut dyn WorkControl) -> Result<()>\",\n175:      \"contract\": \"Exact ramp min(16e9,200e6+max(0,pixels-1048576)*24576), all clip/paint/stroke/grid/dash/interval/boundary/row costs charged, identical count to real traversal including fast fill branches; cancellation is separate. No ThreadLocal budget leakage across jobs. KernelResources is passed explicitly to operations requiring clip/stroke queries; lower writer consumes the shared interface and the coordinator supplies actual implementations.\"\n179:      \"name\": \"dash and grid\",\n185:      \"name\": \"sample and fill\",\n187:      \"contract\": \"Entire original image/pattern interpolation, wrapped indices, clip query, fill+stroke order and source-over math; 4x4 at .125,.375,.625,.875 plus center fast path only eligible interiors. FrozenOracleOnly synthetic-alpha adapter remains test-only.\"\n191:      \"name\": \"filter\",\n197:      \"name\": \"grouped\",\n198:      \"signature\": \"fn render_grouped(view: SceneView<'_>, options: RenderOptions, flat: &mut dyn FlatKernel, control: &mut dyn WorkControl) -> Result<RenderResult>\",\n203:      \"name\": \"evaluate_frame\",\n205:      \"contract\": \"G1 evaluate_view, no parsed track/source clone/reparse; existing overlay order and active flags; instance-specific ancestor transform chains, geometry/paint-bbox/stroke inverse update, deduplicated clip clone with owner-before-suffix. Preserve current unsupported animated effect/pattern/path behavior, classify errors, never silently render static substitute.\"\n209:      \"name\": \"render\",\n210:      \"signature\": \"fn render(view: SceneView<'_>, options: RenderOptions, control: &mut dyn WorkControl) -> Result<RenderResult>; fn render_at(view: SceneView<'_>, time_seconds: f64, options: RenderOptions, control: &mut dyn WorkControl) -> Result<RenderResult>; fn render_flat(view: SceneView<'_>, options: RenderOptions, control: &mut dyn WorkControl) -> Result<RenderResult>\",\n215:      \"name\": \"native operations\",\n216:      \"signature\": \"fn layout_text(request: TextRequest<'_>) -> std::result::Result<TextLayout,MediaError>; fn anchor_offset(advance: f64, anchor: TextAnchor) -> std::result::Result<f64,MediaError>; fn decode_image(encoded: &[u8]) -> std::result::Result<ImagePixels,MediaError>; fn decode_png_data_uri(uri: &[u8]) -> std::result::Result<Vec<u8>,MediaError>; fn scale_bilinear(source: ImageView<'_>, width: u32, height: u32) -> std::result::Result<ImagePixels,MediaError>; fn media_error_name(error: MediaError) -> &'static str\",\n221:      \"name\": \"GIF export\",\n227:  \"context_types\": {\n228:    \"ResolveContext\": \"borrowed source/tokens, mutable accepted ReferenceIndex/CssSheet and PaintCache, SceneBuilder stop transaction, shared ChargeLedger\",\n229:    \"DefinitionContext\": \"struct DefinitionContext<'src, 'ctx> { source: &'src [u8], tokens: &'src [vexel_xml::XmlToken], css: &'ctx mut CssSheet<'src>, references: &'ctx mut ReferenceIndex<'src>, active: &'ctx mut ActiveDefinitions, counters: &'ctx mut DecodeCounters, builder: &'ctx mut SceneBuilder } // source and tokens retain source lifetime; accepted CSS/reference containers borrow that same source; every mutable context/control borrow is independent and temporary; same plus active definition identity stack, scene/shape bounds and immutable inherited contexts\",\n231:    \"ResolvedStyle\": \"typed parsed RGBA/Stroke and source XmlSpan references for deferred paint/clip/filter/mask/marker, opacity, visibility/display/blend/isolation\",\n232:    \"DefinitionPlan<'src>\": \"struct DefinitionPlan<'src> { descriptor: DefinitionDescriptor, expansions: Vec<Expansion<'src>>, post: PostOperation } // expansions preserve CssPaint<'src> source borrows; no engine pointer/callback\",\nuse crate::types::{invalid, stopped};\nuse crate::*;\nimpl ViewMapping {\n    pub fn validate(self) -> Result<()> {\n        if ![self.scale_x, self.scale_y, self.offset_x, self.offset_y]\n            .into_iter()\n            .all(f64::is_finite)\n            || self.scale_x <= 0.0\n            || self.scale_y <= 0.0\n        {\n            Err(invalid(0))\n        } else {\n            Ok(())\n        }\n    }\n    pub fn point(self, point: Point) -> Result<Point> {\n        self.validate()?;\n        let result = Point {\n            x: point.x * self.scale_x + self.offset_x,\n            y: point.y * self.scale_y + self.offset_y,\n        };\n        if !vexel_geometry::finite_point(result) {\n            Err(invalid(0))\n        } else {\n            Ok(result)\n        }\n    }\n}\nimpl PixelBounds {\n    pub fn validate(self, width: u32, height: u32) -> Result<()> {\n        if self.x_first > self.x_last\n            || self.y_first > self.y_last\n            || self.x_last > width\n            || self.y_last > height\n        {\n            Err(invalid(0))\n        } else {\n            Ok(())\n        }\n    }\n}\nimpl BoundaryMask {\n    pub fn validate(&self) -> Result<()> {\n        let required = self\n            .bit_count\n            .checked_add(7)\n            .ok_or_else(crate::memory::arithmetic)?\n            / 8;\n        if self.bits.len() < required || self.marked_pixel_count > self.bit_count {\n            return Err(invalid(0));\n        }\n        Ok(())\n    }\n    pub fn test(&self, pixel: usize) -> Option<bool> {\n        if pixel >= self.bit_count {\n            return None;\n        }\n        let byte = *self.bits.get(pixel / 8)?;\n        Some(byte & (1 << (pixel % 8)) != 0)\n    }\n}\nimpl SampleInput<'_> {\n    pub fn validate(&self, view: SceneView<'_>, control: &mut dyn WorkControl) -> Result<()> {\n        control.checkpoint().map_err(stopped)?;\n        if ![self.px, self.py, self.paint_x, self.paint_y]\n            .into_iter()\n            .all(f64::is_finite)\n            || self.dash_seams.len() != self.local_edges.len()\n        {\n            return Err(invalid(0));\n        }\n        for index in self.active_edges {\n            control.charge(WorkKind::Edge, 1).map_err(stopped)?;\n            if *index as usize >= view.edges.len() {\n                return Err(invalid(0));\n            }\n        }\n        Ok(())\n    }\n}\nimpl Rect {\n    pub fn validate(self) -> Result<()> {\n        if ![self.x, self.y, self.width, self.height]\n            .into_iter()\n            .all(f64::is_finite)\n            || self.width < 0.0\n            || self.height < 0.0\n        {\n            Err(invalid(0))\n        } else {\n            Ok(())\n        }\n    }\n}\n//! Shared owned scalar data and interfaces. Concrete scalar operations live in\n//! their full port modules; there is no default renderer or fallback backend.\nuse crate::*;\n#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]\npub struct PixelBounds {\n    pub x_first: u32,\n    pub x_last: u32,\n    pub y_first: u32,\n    pub y_last: u32,\n    pub visible: bool,\n}\n#[derive(Debug, Clone, Copy, PartialEq, Default)]\npub struct ShapeBounds {\n    pub device_left: f64,\n    pub device_top: f64,\n    pub device_right: f64,\n    pub device_bottom: f64,\n    pub pixels: PixelBounds,\n}\n#[derive(Debug, Default)]\npub struct BoundsSet {\n    pub shapes: Vec<ShapeBounds>,\n    pub pixel_count: usize,\n}\n#[derive(Debug, Default)]\npub struct BoundaryMask {\n    pub bits: Vec<u8>,\n    pub bit_count: usize,\n    pub marked_pixel_count: usize,\n    pub mark_work: usize,\n}\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub struct ScanlineEvent {\n    pub slot: usize,\n    pub edge: u32,\n    pub add: bool,\n}\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub struct ShapeRowEvent {\n    pub row: u32,\n    pub shape: u32,\n    pub add: bool,\n}\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub struct ScanlineNode {\n    pub left: i32,\n    pub right: i32,\n    pub height: i32,\n}\n#[derive(Debug)]\npub struct ScanlineIndex {\n    pub events: Vec<ScanlineEvent>,\n    pub nodes: Vec<ScanlineNode>,\n    pub roots: Vec<i32>,\n    pub shape_events: Vec<ShapeRowEvent>,\n    pub shape_nodes: Vec<ScanlineNode>,\n    pub shape_root: i32,\n    pub event_cursor: usize,\n    pub shape_event_cursor: usize,\n    pub shape_count: usize,\n    pub edge_count: usize,\n    pub scanline_count: usize,\n    pub listed_edge_count: usize,\n}\nimpl Default for ScanlineIndex {\n    fn default() -> Self {\n        Self {\n            events: Vec::new(),\n            nodes: Vec::new(),\n            roots: Vec::new(),\n            shape_events: Vec::new(),\n            shape_nodes: Vec::new(),\n            shape_root: -1,\n            event_cursor: 0,\n            shape_event_cursor: 0,\n            shape_count: 0,\n            edge_count: 0,\n            scanline_count: 0,\n            listed_edge_count: 0,\n        }\n    }\n}\n#[derive(Debug, Default)]\npub struct RowBuffers {\n    pub shape_offsets: Vec<usize>,\n    pub active_edges: Vec<u32>,\n    pub active_shapes: Vec<u32>,\n}\n#[derive(Debug, Clone, Copy, PartialEq, Default)]\npub struct FillInterval {\n    pub left: f64,\n    pub right: f64,\n}\n#[derive(Debug, Clone, Copy, PartialEq)]\npub struct FillCrossing {\n    pub x: f64,\n    pub winding_delta: i32,\n    pub edge_index: u32,\n}\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub struct PixelRun {\n    pub first_x: u32,\n    pub end_x