 let style = shared.compute_style(ElementId(0), None, &mut Run).unwrap();\n    assert_eq!(style.value(Property::Fill).unwrap().bytes, b\"red\");\n    let offset = source.windows(4).position(|b| b == b\"\\\"p\\\"/\").unwrap() + 1;\n    assert!(\n        shared\n            .find_reference(XmlSpan { offset, length: 1 }, &mut Run)\n            .unwrap()\n            .is_some()\n    );\n    assert!(shared.element(ElementId(usize::MAX), 1, &mut Run).is_err());\n    assert!(DecodeSource::new(&source, &tokens[..r.token_count], &mut StopAfter(0)).is_err());\n    assert!(Arc::ptr_eq(shared.source_owner(), &source));\n}\n// Trait implementation is compile/lifetime evidence only. Unsupported unused\n// methods cannot be mistaken for a production decoder or scalar kernel.\nstruct ContractAdapter;\nimpl DecodeOperations for ContractAdapter {\n    fn resolve_paint(\n        &mut self,\n        _: &mut ResolveContext<'_, '_>,\n        _: XmlSpan,\n        _: &[Edge],\n        _: Affine,\n        _: [f64; 2],\n        _: &mut dyn WorkControl,\n    ) -> Result<ResolvedPaint> {\n        Err(Diagnostic {\n            kind: ErrorKind::Unsupported,\n            offset: 0,\n        })\n    }\n    fn plan_definition<'src, 'ctx>(\n        &mut self,\n        ctx: &mut DefinitionContext<'src, 'ctx>,\n        _: DefinitionKind,\n        element: ElementId,\n        _: ShapeId,\n        transform: Affine,\n        _: [f64; 4],\n        _: &CssPaint<'src>,\n        control: &mut dyn WorkControl,\n    ) -> Result<DefinitionPlan<'src>> {\n        ctx.validate()?;\n        let style = ctx.shared.compute_style(element, None, control)?;\n        Ok(DefinitionPlan {\n            descriptor: DefinitionDescriptor::Marker(MarkerDescriptor {\n                definition: element,\n                viewport: [1., 1.],\n                transform,\n                error_offset: 0,\n            }),\n            expansions: vec![Expansion {\n                range: TableRange {\n                    first: element.0,\n                    count: 1,\n                },\n                transform,\n                viewport: [1., 1.],\n                style,\n                flavor: DecodeFlavor::Marker,\n                post: PostOperation::FinishMarker,\n            }],\n            post: PostOperation::None,\n        })\n    }\n    fn decode_text(\n        &mut self,\n        _: TextDecodeRequest<'_, '_>,\n        _: &mut SceneBuilder,\n        _: &mut dyn WorkControl,\n    ) -> Result<bool> {\n        Err(Diagnostic {\n            kind: ErrorKind::Unsupported,\n            offset: 0,\n        })\n    }\n    fn decode_image(\n        &mut self,\n        _: ImageDecodeRequest<'_, '_>,\n        _: &mut SceneBuilder,\n        _: &mut dyn WorkControl,\n    ) -> Result<ShapeId> {\n        Err(Diagnostic {\n            kind: ErrorKind::Unsupported,\n            offset: 0,\n        })\n    }\n}\n#[test]\nfn definition_plan_outlives_mutable_context_and_control_without_source_copy() {\n    let source = owner();\n    let (tokens, r) = vexel_xml::tokenize(&source, Default::default());\n    let mut shared = DecodeSource::new(&source, &tokens[..r.token_count], &mut Run).unwrap();\n    let mut b = SceneBuilder::new(\n        source.clone(),\n        animation(&source),\n        0,\n        viewport(),\n        Default::default(),\n    )\n    .unwrap();\n    let root = b.root_id();\n    let id = b.append_shape(root, shape(&source), &mut Run).unwrap();\n    let mut active = ActiveDefinitions::default();\n    let mut ledger = ChargeLedger::new(&source, 1 << 20, 64).unwrap();\n    let mut adapter = ContractAdapter;\n    let plan = {\n        let mut ctx = DefinitionContext {\n            shared: &mut shared,\n            builder: &mut b,\n            scene: root,\n            active: &mut active,\n            ledger: &mut ledger,\n        };\n        let operations: &mut dyn DecodeOperations = &mut adapter;\n        operations\n            .plan_definition(\n                &mut ctx,\n                DefinitionKind::Marker,\n                ElementId(0),\n                id,\n                vexel_geometry::affine_identity(),\n                [0., 0., 1., 1.],\n                &CssPaint::initial(),\n                &mut Run,\n            )\n            .unwrap()\n    };\n    shared.compute_style(ElementId(0), None, &mut Run).unwrap();\n    b.record_ignored(IgnoredKind::Meta, 0).unwrap();\n    assert_eq!(plan.expansions.len(), 1);\n    assert_eq!(plan.expansions[0].range.first, 0);\n}\n#[test]\nfn temporary_definition_context_rejects_an_equal_bytes_wrong_source_owner() {\n    let source = owner();\n    let other = Arc::new(source.as_slice().to_vec());\n    let (tokens, r) = vexel_xml::tokenize(&source, Default::default());\n    let mut shared = DecodeSource::new(&source, &tokens[..r.token_count], &mut Run).unwrap();\n    let mut b = SceneBuilder::new(\n        other.clone(),\n        animation(&other),\n        0,\n        viewport(),\n        Default::default(),\n    )\n    .unwrap();\n    let root = b.root_id();\n    let mut active = ActiveDefinitions::default();\n    let mut ledger = ChargeLedger::new(&source, 1 << 20, 64).unwrap();\n    let ctx = DefinitionContext {\n        shared: &mut shared,\n        builder: &mut b,\n        scene: root,\n        active: &mut active,\n        ledger: &mut ledger,\n    };\n    assert_eq!(ctx.validate().unwrap_err().kind, ErrorKind::InvalidArgument);\n}\n#[test]\nfn all_public_dependency_traits_are_object_safe_without_stub_backends() {\n    fn interfaces(\n        _: Option<&dyn KernelResources>,\n        _: Option<&mut dyn FlatKernel>,\n        _: Option<&mut dyn DecodeOperations>,\n        _: Option<&mut dyn DecodeSession>,\n    ) {\n    }\n    interfaces(None, None, None, None);\n}\n#[test]\nfn public_element_views_reject_malformed_payload_spans_and_poll_each_token() {\n    let source = owner();\n    let (mut tokens, r) = vexel_xml::tokenize(&source, Default::default());\n    let view = ElementView {\n        source: &source,\n        tokens: &tokens[..r.token_count],\n        element: ElementId(0),\n        end: r.token_count,\n    };\n    assert!(view.validate(&mut Run).is_ok());\n    assert_eq!(\n        view.validate(&mut StopAfter(1)).unwrap_err().kind,\n        ErrorKind::Canceled\n    );\n    tokens[1].value = XmlSpan {\n        offset: usize::MAX,\n        length: 2,\n    };\n    let view = ElementView {\n        source: &source,\n        tokens: &tokens[..r.token_count],\n        element: ElementId(0),\n        end: r.token_count,\n    };\n    assert_eq!(\n        view.validate(&mut Run).unwrap_err().kind,\n        ErrorKind::InvalidArgument\n    );\nuse crate::{Diagnostic, ErrorKind, Result};\n/// Checked half-open table range, with no raw pointers.\n#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]\npub struct TableRange {\n    pub first: usize,\n    pub count: usize,\n}\nimpl TableRange {\n    pub const EMPTY: Self = Self { first: 0, count: 0 };\n    pub fn end(self) -> Option<usize> {\n        self.first.checked_add(self.count)\n    }\n    pub fn slice<T>(self, values: &[T]) -> Option<&[T]> {\n        values.get(self.first..self.end()?)\n    }\n    pub(crate) fn require(self, length: usize, offset: usize) -> Result<()> {\n        if self.end().is_some_and(|end| end <= length) {\n            Ok(())\n        } else {\n            Err(Diagnostic {\n                kind: ErrorKind::InvalidArgument,\n                offset,\n            })\n        }\n    }\n}\n/// Source token identity. Decoders validate it against their retained token stream.\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub struct ElementId(pub usize);\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub struct SceneId {\n    pub(crate) owner: u64,\n    pub(crate) slot: u32,\n    pub(crate) serial: u64,\n}\nimpl SceneId {\n    pub fn index(self) -> usize {\n        self.slot as usize\n    }\n}\nmacro_rules! handles { ($($name:ident),*) => { $(\n    #[derive(Debug, Clone, Copy, PartialEq, Eq)]\n    pub struct $name { pub(crate) owner: u64, pub(crate) scene: u32, pub(crate) slot: u32, pub(crate) serial: u64 }\n    impl $name { pub fn index(self) -> usize { self.slot as usize } }\n)* }; }\nhandles!(\n    ShapeId,\n    TransformId,\n    ClipId,\n    PatternId,\n    MaskId,\n    FilterId,\n    GroupId\n);\n#![forbid(unsafe_code)]\n//! Owned scene data. SVG decoding, scalar rendering and native providers are separate gates.\nmod builder;\nmod ids;\nmod media;\nmod memory;\nmod model;\nmod mutators;\nmod shape_builder;\nmod types;\nmod validate;\npub use builder::*;\npub use ids::*;\npub use media::*;\npub use memory::*;\npub use model::*;\npub use types::*;\npub use vexel_base::{Span, Stop, WorkControl, WorkKind};\npub use vexel_geometry::{Affine, Edge, Point};\npub use vexel_svg_animation::{DocumentView as AnimationView, OwnedDocument as OwnedAnimation};\npub type SourceOwner = std::sync::Arc<Vec<u8>>;\n#[cfg(test)]\nmod validation_tests;\n\nmod accounting;\nmod contract_validate;\nmod decode_contract;\nmod pattern_ticket;\nmod render_contract;\npub use accounting::*;\npub use decode_contract::*;\npub use pattern_ticket::*;\npub use render_contract::*;\nmod frame;\npub use frame::*;\nmod contract_storage;\nmod source_context;\npub use source_context::*;\n","exit_code":0,"status":"completed"}}
